import random
from collections import deque

def shortest_path_dist(n, adj, u, v):
    # BFS from u to v
    if u == v:
        return 0
    visited = [-1]*n
    q = deque([u])
    visited[u] = 0
    while q:
        x = q.popleft()
        for y in adj[x]:
            if visited[y] == -1:
                visited[y] = visited[x] + 1
                if y == v:
                    return visited[y]
                q.append(y)
    return float('inf')

def build_random_graph(n=19, target_edges=29):
    edges = []
    adj = [set() for _ in range(n)]
    possible = [(i,j) for i in range(n) for j in range(i+1,n)]
    random.shuffle(possible)
    for u,v in possible:
        # check distance between u and v in current graph
        # if distance <=5, adding edge creates cycle of length <=6
        # Actually if distance d exists, adding edge creates cycle of length d+1.
        # We need girth >=7, so no cycles of length <=6.
        # So we require distance >=6 or infinite.
        # BFS from u to v
        dist = shortest_path_dist(n, adj, u, v)
        if dist >= 6:
            edges.append((u,v))
            adj[u].add(v)
            adj[v].add(u)
            if len(edges) >= target_edges:
                return edges, adj
    return edges, adj

def is_3_colorable(n, adj):
    colors = [-1]*n
    order = list(range(n))
    # sort by degree descending for heuristic
    order.sort(key=lambda x: len(adj[x]), reverse=True)

    def backtrack(idx):
        if idx == n:
            return True
        v = order[idx]
        # find color
        used = [False]*3
        for nb in adj[v]:
            if colors[nb] != -1:
                used[colors[nb]] = True
        for c in range(3):
            if not used[c]:
                colors[v] = c
                if backtrack(idx+1):
                    return True
                colors[v] = -1
        return False
    return backtrack(0)

