from pysat.solvers import Solver
from pysat.card import CardEnc
from itertools import combinations
from collections import deque

n = 19
min_edges = 29

# Map each possible edge to a variable
edge_vars = {}
var_counter = 1
for u in range(n):
    for v in range(u+1, n):
        edge_vars[(u,v)] = var_counter
        var_counter += 1

num_edge_vars = var_counter - 1

def get_var(u, v):
    if u > v:
        u, v = v, u
    return edge_vars[(u,v)]

def edges_from_model(model):
    edges = []
    for var in model:
        if var > 0 and var <= num_edge_vars:
            for (u,v), idx in edge_vars.items():
                if idx == var:
                    edges.append((u,v))
                    break
    return edges

def build_adj(n, edges):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    return adj

def girth(n, adj):
    best = float('inf')
    for start in range(n):
        dist = [-1]*n
        parent = [-1]*n
        q = deque([start])
        dist[start] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v and parent[v] != u:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < best:
                        best = cycle_len
                    if best == 3:
                        return 3
    return best

def find_short_cycles(n, adj, max_len=6):
    """Find all cycles of length <= max_len"""
    cycles = []
    for start in range(n):
        # BFS to find cycles from start
        dist = [-1]*n
        parent = [-1]*n
        q = deque([start])
        dist[start] = 0
        while q:
            u = q.popleft()
            if dist[u] >= max_len:
                continue
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v and parent[v] != u:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= max_len:
                        # Reconstruct cycle edges
                        # Path from start to u and start to v
                        path_u = []
                        x = u
                        while x != start:
                            path_u.append(x)
                            x = parent[x]
                        path_u.append(start)

                        path_v = []
                        x = v
                        while x != start:
                            path_v.append(x)
                            x = parent[x]
                        path_v.append(start)

                        # Cycle is path_u reversed + path_v + edge(u,v)
                        cycle_vertices = list(reversed(path_u)) + path_v[1:]
                        cycle_edges = []
                        for i in range(len(cycle_vertices)):
                            a, b = cycle_vertices[i], cycle_vertices[(i+1)%len(cycle_vertices)]
                            if a > b:
                                a, b = b, a
                            cycle_edges.append((a,b))
                        cycles.append(tuple(sorted(set(cycle_edges))))
    return list(set(cycles))

def is_3_colorable(n, adj):
    colors = [-1]*n
    order = list(range(n))
    order.sort(key=lambda x: len(adj[x]), reverse=True)

    def backtrack(idx):
        if idx == n:
            return True
        v = order[idx]
        used = [False]*3
        for nb in adj[v]:
            if colors[nb] != -1:
                used[colors[nb]] = True
        for c in range(3):
            if not used[c]:
                colors[v] = c
                if backtrack(idx+1):
                    return True
                colors[v] = -1
        return False
    return backtrack(0)

# Iterative SAT solving
forbidden_cycles = set()
max_iters = 50

for iteration in range(max_iters):
    print(f"Iteration {iteration}, forbidden cycles: {len(forbidden_cycles)}")

    with Solver(name='g3') as solver:
        # At least 29 edges
        at_least = CardEnc.atleast(lits=list(range(1, num_edge_vars+1)), bound=min_edges, encoding=1)
        for clause in at_least.clauses:
            solver.add_clause(clause)

        # No 3-cycles
        for a, b, c in combinations(range(n), 3):
            solver.add_clause([-get_var(a,b), -get_var(b,c), -get_var(a,c)])

        # Forbidden cycles from previous iterations
        for cycle_edges in forbidden_cycles:
            clause = [-get_var(u,v) for u,v in cycle_edges]
            solver.add_clause(clause)

        if solver.solve():
            model = solver.get_model()
            edges = edges_from_model(model)
            adj = build_adj(n, edges)
            g = girth(n, adj)
            print(f"  Found graph with {len(edges)} edges, girth={g}")

            if g >= 7:
                print("  Girth constraint satisfied!")
                if is_3_colorable(n, adj):
                    print("  3-colorable! Solution found!")
                    print(edges)
                    break
                else:
                    print("  Not 3-colorable, adding constraints...")
                    # This is harder - we'd need to add non-3-colorable constraints
                    # For now, let's just try again with some random perturbation
                    # by forbidding some edges
                    import random
                    forbidden_cycles.add(tuple(edges[:5]))  # forbid first 5 edges
            else:
                # Find short cycles and forbid them
                cycles = find_short_cycles(n, adj, max_len=6)
                print(f"  Found {len(cycles)} short cycles, forbidding them")
                for cycle in cycles:
                    forbidden_cycles.add(cycle)
        else:
            print("  UNSAT")
            break
else:
    print("Max iterations reached")
